//! Local-only minimum Writer witness. Never supply genuine Save to CI. Stdout is a candidate only after Verify.
use hkia_save_core::{archive::MAX_ARCHIVE,session::*,writer::{Edit,FWISHES_GUID,FWISHES_COUNTER_GUID},native::ModelState};
use std::io::{self,Read,Write};
fn page(s:&mut ProductSession,id:&mut u64,domain:Domain)->Result<Vec<Row>,()>{let mut rows=Vec::new();let mut offset=0;loop{*id+=1;let expected=s.stamp();let r=s.dispatch(Request{id:*id,expected,command:Command::IndexPage{domain,offset,limit:128}});let Ok(Payload::Page(p))=r.result else{return Err(())};let n=p.rows.len()as u32;if n==0&&offset<p.total{return Err(())}rows.extend(p.rows);offset+=n;if offset==p.total{return Ok(rows)}}}
fn w(s:&mut ProductSession,id:&mut u64,command:WriterCommand)->Result<WriterReply,()>{*id+=1;let expected=s.stamp();let r=s.dispatch_writer(WriterRequest{id:*id,expected,command});if r.result.is_err(){Err(())}else{Ok(r)}}
fn run()->Result<(),()>{let args:Vec<_>=std::env::args().collect();if args.len()!=3||args[1]!="--private-writer"||!matches!(args[2].as_str(),"history"|"progress"|"batch"){return Err(())}let mut raw=Vec::new();io::stdin().take((MAX_ARCHIVE+1)as u64).read_to_end(&mut raw).map_err(|_|())?;let mut s=ProductSession::new_private_writer([3;16]).map_err(|_|())?;let mut id=1;let expected=s.stamp();s.dispatch(Request{id,expected,command:Command::Open{kind:InputKind::Zip,bytes:raw}}).result.map_err(|_|())?;let mut edits=Vec::new();if args[2]!="progress"{let rows=page(&mut s,&mut id,Domain::CollectionHistory)?;let h=rows.iter().find_map(|r|match r{Row::Collection(c)if c.ticks>0&&c.ticks<=3_155_378_975_989_999_999=>Some(c),_=>None}).ok_or(())?;edits.push(Edit::History{item:h.id,old:h.ticks,next:h.ticks+10_000_000});}if args[2]!="history"{let a=page(&mut s,&mut id,Domain::SlotAchievement)?;let c=page(&mut s,&mut id,Domain::SlotCounter)?;let a=a.iter().find_map(|r|match r{Row::Slot(m)if m.guid==FWISHES_GUID=>Some(m),_=>None}).ok_or(())?;let c=c.iter().find_map(|r|match r{Row::Slot(m)if m.guid==FWISHES_COUNTER_GUID=>Some(m),_=>None}).ok_or(())?;let ModelState::Achievement{current,complete:false,..}=a.state else{return Err(())};edits.push(Edit::FwishesProgress{achievement:a.id,counter:c.id,old_bits:current.to_bits(),next_bits:0});}let r=w(&mut s,&mut id,WriterCommand::Plan{edits})?;let Ok(WriterPayload::Plan(p))=r.result else{return Err(())};let r=w(&mut s,&mut id,WriterCommand::Preview{plan:p.id})?;let Ok(WriterPayload::Preview{proof,..})=r.result else{return Err(())};let r=w(&mut s,&mut id,WriterCommand::Apply{plan:p.id})?;if r.result!=Ok(WriterPayload::Applied(proof.clone())){return Err(())}let r=w(&mut s,&mut id,WriterCommand::Verify)?;if r.result!=Ok(WriterPayload::Verified(proof)){return Err(())}let r=w(&mut s,&mut id,WriterCommand::Export)?;let out=r.output.ok_or(())?;io::stdout().lock().write_all(&out).map_err(|_|())?;Ok(())}
fn main(){if run().is_err(){std::process::exit(1)}}
